-- DryZen / OpenCart 3
-- Preslagivanje naslovnice prema odobrenom sadržaju, bez promjene postojećeg vizualnog smjera.
-- Uključuje HR/EN sadržaj, poredak modula, stvarne recenzije, newsletter i footer.
-- Skripta je idempotentna i može se sigurno pokrenuti više puta.
-- Projekt koristi prefiks tablica `oc_`; prilagodite ga ako je na live bazi drukčiji.
-- Prvo deployajte kod iz iste grane, zatim importajte ovu datoteku.

START TRANSACTION;

-- Ukloni samo zastarjeli homepage CSS iz postavke; ostali custom CSS ostaje netaknut.
SET @dryzen_custom_css := COALESCE((
  SELECT `value` FROM `oc_setting`
  WHERE `store_id` = 0 AND `code` = 'basel' AND `key` = 'basel_custom_css'
  ORDER BY `setting_id` LIMIT 1
), '');
SET @dryzen_marker_start := LOCATE('/* DRYZEN_LANDING_UX_START */', @dryzen_custom_css);
SET @dryzen_marker_end := LOCATE('/* DRYZEN_LANDING_UX_END */', @dryzen_custom_css);
SET @dryzen_custom_css := IF(
  @dryzen_marker_start > 0 AND @dryzen_marker_end > @dryzen_marker_start,
  CONCAT(SUBSTRING(@dryzen_custom_css, 1, @dryzen_marker_start - 1), SUBSTRING(@dryzen_custom_css, @dryzen_marker_end + LENGTH('/* DRYZEN_LANDING_UX_END */'))),
  @dryzen_custom_css
);
SET @dryzen_legacy_start := LOCATE('#mod2 .type-img,', @dryzen_custom_css);
SET @dryzen_legacy_end := LOCATE('/* DRYZEN_NEED_HANDS_UX_START */', @dryzen_custom_css);
SET @dryzen_custom_css := IF(
  @dryzen_legacy_start > 0 AND @dryzen_legacy_end > @dryzen_legacy_start,
  CONCAT(SUBSTRING(@dryzen_custom_css, 1, @dryzen_legacy_start - 1), SUBSTRING(@dryzen_custom_css, @dryzen_legacy_end)),
  @dryzen_custom_css
);
UPDATE `oc_setting` SET `value` = TRIM(@dryzen_custom_css)
WHERE `store_id` = 0 AND `code` = 'basel' AND `key` = 'basel_custom_css';

-- Kreiraj ili ažuriraj homepage module prema stabilnom nazivu.
