SELECT CONVERT(0x4472795a656e204865726f USING utf8mb4), CONVERT(0x626173656c5f636f6e74656e74 USING utf8mb4), @dryzen_module_hero_setting
WHERE NOT EXISTS (
  SELECT 1 FROM `oc_module` WHERE `code` = CONVERT(0x626173656c5f636f6e74656e74 USING utf8mb4) AND `name` = CONVERT(0x4472795a656e204865726f USING utf8mb4)
