-- Zamijeni samo top module na Home layoutu, u traženom redoslijedu.
SET @dryzen_home_layout := (
  SELECT MIN(`layout_id`) FROM `oc_layout_route` WHERE `route` = CONVERT(0x636f6d6d6f6e2f686f6d65 USING utf8mb4)
);
DELETE FROM `oc_layout_module` WHERE `layout_id` = @dryzen_home_layout AND `position` = 'top';
INSERT INTO `oc_layout_module` (`layout_id`, `code`, `position`, `sort_order`) VALUES
(@dryzen_home_layout, CONCAT(CONVERT(0x626173656c5f636f6e74656e742e USING utf8mb4), @dryzen_module_hero), 'top', 1);
INSERT INTO `oc_layout_module` (`layout_id`, `code`, `position`, `sort_order`) VALUES
(@dryzen_home_layout, CONCAT(CONVERT(0x626173656c5f636f6e74656e742e USING utf8mb4), @dryzen_module_products_intro), 'top', 2);
