  SELECT 1 FROM `oc_setting` WHERE `store_id` = 0 AND `code` = CONVERT(0x626173656c USING utf8mb4) AND `key` = CONVERT(0x6f76657277726974655f666f6f7465725f6c696e6b73 USING utf8mb4)
);

COMMIT;

